// The channels come as ?handles=@one,@two. At most ten, and only well-formed handles.
const handles = String($json.query?.handles ?? '')
  .split(',')
  .map((handle) => handle.trim())
  .filter((handle) => /^@[\w.-]{3,30}$/.test(handle));
return [...new Set(handles)].slice(0, 10).map((handle) => ({ json: { handle } }));

// A channel's feed is found by its id, which its page gives in the canonical link.
const page = String($json.data ?? '');
const handle = $('List the channels').item.json.handle;
const id = page.match(/<link rel="canonical" href="https:\/\/www\.youtube\.com\/channel\/(UC[\w-]{22})"/)?.[1] ?? '';
const name = page.match(/<meta property="og:title" content="([^"]*)"/)?.[1] ?? handle;
return { json: { handle, id, name } };

// The public feed lists a channel's latest 15 videos, Shorts included, with their views and likes.
const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };
const decode = (text) => text.replace(/&(#\d+|\w+);/g, (all, code) => (code[0] === '#' ? String.fromCodePoint(Number(code.slice(1))) : ENTITIES[code] ?? all));
const pick = (text, pattern) => text.match(pattern)?.[1] ?? '';

const found = $('Find the channel id').all().map((item) => item.json);
const feeds = $input.all();
const channels = found.map((channel, at) => {
  const name = decode(channel.name);
  if (!channel.id) return { handle: channel.handle, name, found: false, videos: [], views: 0, perVideo: 0 };
  const xml = String(feeds[at]?.json?.data ?? '');
  const videos = [...xml.matchAll(/<entry>([\s\S]*?)<\/entry>/g)].map(([, entry]) => ({
    title: decode(pick(entry, /<title>([^<]*)<\/title>/)),
    link: pick(entry, /<link rel="alternate" href="([^"]+)"/),
    published: pick(entry, /<published>([^<]+)<\/published>/),
    views: Number(pick(entry, /<media:statistics views="(\d+)"/) || 0),
    likes: Number(pick(entry, /<media:starRating count="(\d+)"/) || 0),
  }));
  const views = videos.reduce((sum, video) => sum + video.views, 0);
  return { handle: channel.handle, name, found: true, videos, views, perVideo: videos.length ? Math.round(views / videos.length) : 0 };
});
return [{ json: { checkedAt: new Date().toISOString(), channels } }];
